"""
setup.py

Bootstraps the observability pipeline project structure. Running this
script creates the `src/` and `data/` directories (if they don't already
exist) and writes out every module in the pipeline, plus the Docker
setup for running it alongside Memgraph:

    src/__init__.py
    src/generator.py     - faker-based synthetic log generation
    src/db_handler.py    - Memgraph ingestion + FAILED_TOGETHER correlation
    src/detector.py      - pandas rolling-window failure-burst detection
    src/clusterer.py     - TF-IDF + DBSCAN error log clustering
    src/ai_synthesis.py  - Gemini API incident/post-mortem report generation
    main.py               - end-to-end CLI batch runner
    app.py                - FastAPI + WebSocket live streaming server
    requirements.txt
    Dockerfile            - container image for main.py / app.py
    docker-compose.yml    - app + memgraph-platform (Memgraph+MAGE+Lab) wiring
    .dockerignore
    .env.example          - GEMINI_API_KEY and stream-tuning env vars

`data/` is created empty (with a .gitkeep) as the default output location
for generated logs, alerts, clusters, and incident reports.

Usage:
    python setup.py
    # then, locally:
    pip install -r requirements.txt
    python main.py --count 2000 --skip-db --skip-ai
    # or, in Docker:
    cp .env.example .env   # fill in GEMINI_API_KEY if you want AI reports
    docker compose up --build
    # Memgraph Lab UI: http://localhost:3000
"""

import os

