def write_file(path: str, content: str, overwrite: bool) -> None:
    parent = os.path.dirname(path)
    if parent:
        os.makedirs(parent, exist_ok=True)

    if os.path.exists(path) and not overwrite:
        print(f"  skip   {path} (already exists, use --force to overwrite)")
        return

    with open(path, "w") as f:
        f.write(content)
    print(f"  wrote  {path}")


def main() -> None:
    import argparse

    parser = argparse.ArgumentParser(
        description="Bootstrap the observability pipeline project structure."
    )
    parser.add_argument(
        "--force", action="store_true",
        help="Overwrite files that already exist (default: skip existing files).",
    )
    args = parser.parse_args()

    print("Creating project structure...")
    os.makedirs("src", exist_ok=True)
    os.makedirs("data", exist_ok=True)
    print("  dir    src/")
    print("  dir    data/")

    print("Writing source files...")
    for path, content in FILES.items():
        write_file(path, content, overwrite=args.force)

    write_file("data/.gitkeep", DATA_GITKEEP_CONTENT, overwrite=args.force)

    print()
    print("Done. Next steps:")
    print("  pip install -r requirements.txt")
    print("  python main.py --count 2000 --skip-db --skip-ai   # quick smoke test")
    print("  uvicorn app:app --reload                          # live WebSocket server")
    print("  --- or, in Docker ---")
